// Why :key matters: patching is per-node identity.
// rows = [{ id: 11, name: "ana" }, { id: 12, name: "bo" }]

// With :key="row.id", removing the first row patches one node away.
// With :key="index", Vue reuses node 0 for "bo", node 1 for "ana"...
// every row shifts, inputs keep stale local state, animations misfire.

import { ref, computed } from "vue"

const rows = ref([
  { id: 11, name: "ana", score: 3 },
  { id: 12, name: "bo", score: 9 },
  { id: 13, name: "cy", score: 1 }
])

// Cached derivation: recomputes only when rows changes.
const ranked = computed(() =>
  [...rows.value].sort((a, b) => b.score - a.score)
)

// Rendering plan (in template):
//   <li v-for="row in ranked" :key="row.id">{{ row.name }}</li>
//
// v-memo for an expensive row renderer, invalidating only on what matters:
//   <li v-for="row in ranked" :key="row.id"
//       v-memo="[row.id, row.score]">...heavy markup...</li>
